<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { PhPlus, PhArrowUp, PhArrowsClockwise, PhChatsCircle, PhFolderSimple, PhPlug, PhX, PhArrowBendUpLeft, PhCopy, PhCheckCircle, PhFileText, PhUsers, PhGearSix, PhArrowSquareOut } from '@phosphor-icons/vue'
import { native, transport } from './bridge'
import { createCollaborationStore } from './store'
import { configInstructions, connectionLabel, hostConfig, hostNames, taskNames, type Agent, type Artifact, type Binding, type Connection, type Message, type Task } from './model'
const store=createCollaborationStore(transport), s=store.state
const room=computed(()=>s.rooms.find(r=>r.id===s.roomId))
const draft=computed({get:()=>s.drafts[store.key()]||'',set:(value:string)=>{s.drafts[store.key()]=value}})
const sidebar=ref<'agents'|'tasks'>('agents'), modal=ref(''), dialog=ref<HTMLDialogElement>(), list=ref<HTMLElement>()
const form=ref({server_url:import.meta.env.VITE_COLLABORATION_DEV_SERVER||'http://127.0.0.1:8797',username:'',password:'',display_name:'',invite_token:'',mode:'login'})
const invitation=ref(''), invitationExpiry=ref('')
const projectName=ref(''), memberName=ref(''), contextDraft=ref(''), contextVersion=ref(0)
const taskForm=ref({title:'',description:'',acceptance_criteria:'',target_username:''})
const bindingForm=ref({host_kind:'codex',label:'',host_ref:'',scope:'project',executable:''})
const selectedBinding=ref<Binding|null>(null), selectedAgent=ref<Agent|null>(null), selectedTask=ref<Task|null>(null)
const artifacts=ref<Artifact[]>([]), artifact=ref<Artifact|null>(null), run=ref<Record<string,unknown>|null>(null)
const authorizeAgent=ref(''), permit=ref(''), permitExpiry=ref(''), reviewReason=ref(''), copied=ref(false)
const canEditContext=computed(()=>['owner','admin'].includes(room.value?.role||''))
watch(()=>s.tasks, tasks=>{if(selectedTask.value){const fresh=tasks.find(t=>t.id===selectedTask.value?.id);if(fresh){if(fresh.version!==selectedTask.value.version){permit.value='';permitExpiry.value=''}selectedTask.value=fresh}}})
const mine=computed(()=>s.agents.filter(a=>a.owner_user_id===s.connection.user?.id))
const canReview=computed(()=>selectedTask.value?.created_by===s.connection.user?.id||['owner','admin'].includes(room.value?.role||''))
const bindConfig=computed(()=>selectedBinding.value?hostConfig(selectedBinding.value):'')
const permitPrompt=computed(()=>permit.value&&selectedTask.value?`请只处理任务 ${selectedTask.value.id}。调用 task_start，execution_mode=user_triggered，idempotency_key=${selectedTask.value.id}-v${selectedTask.value.version}，authorization_token=${permit.value}。许可只用于工具参数，不写入消息或成果；完成后提交成果并等待人类验收。`:'')
const reply=computed(()=>s.messages.find(m=>m.id===s.replyId))
function sender(m:Message) { return m.sender_agent_instance_id ? s.agents.find(a=>a.id===m.sender_agent_instance_id)?.label||`Agent ${m.sender_agent_instance_id.slice(0,6)}` : s.members.find(u=>u.user_id===m.sender_user_id)?.display_name||'项目成员' }
function host(m:Message) {return m.sender_agent_instance_id?hostNames[s.agents.find(a=>a.id===m.sender_agent_instance_id)?.host_kind||'']||'Agent':'成员'}
function time(value:string|number) { return new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}) }
function open(kind:string) {s.error='';s.notice='';copied.value=false;modal.value=kind}
function close() {modal.value='';invitation.value='';invitationExpiry.value='';permit.value='';permitExpiry.value='';form.value.password='';copied.value=false}
watch(modal,async value=>{await nextTick();if(value&&!dialog.value?.open)dialog.value?.showModal();if(!value&&dialog.value?.open)dialog.value.close()})
watch(()=>s.roomId,()=>{close();selectedTask.value=null;artifact.value=null;artifacts.value=[]})
watch(()=>s.connection.user?.id,()=>{if(!s.connection.user)close()})
watch(()=>s.messages.length,async()=>{await nextTick();if(list.value)list.value.scrollTop=list.value.scrollHeight})
watch(()=>bindingForm.value.host_kind,host=>{bindingForm.value.scope=host==='dsh'?'profile':host==='aiwork'?'session':'project'})
async function login() {const p={...form.value};form.value.password='';await store.connect(p);if(!s.error)close()}
async function addProject(){await store.createRoom(projectName.value);if(!s.error){projectName.value='';close()}}
async function copy(value:string){try{await navigator.clipboard.writeText(value);copied.value=true}catch{s.error='无法访问剪贴板，请选中文本手动复制'}}
function editContext(){contextDraft.value=s.context.body;contextVersion.value=s.context.version;open('context')}
async function saveContext(){await store.act(async()=>{await store.request('PUT',`/v1/rooms/${s.roomId}/context`,{body:contextDraft.value,expected_version:contextVersion.value});await store.refresh();close()})}
async function invite(){await store.act(async()=>{const result=await store.request<{invite_token:string;expires_at:string}>('POST','/v1/auth/invites',{note:'项目协作注册',ttl_hours:24});invitation.value=result.invite_token;invitationExpiry.value=result.expires_at})}
async function addMember(){await store.act(async()=>{await store.request('POST',`/v1/rooms/${s.roomId}/members`,{username:memberName.value.trim(),role:'member'});await store.refresh();memberName.value='';close()})}
async function addTask(){await store.act(async()=>{await store.request('POST',`/v1/rooms/${s.roomId}/tasks`,{...taskForm.value,assignment_mode:taskForm.value.target_username?'directed':'open',required_permission:'read_only',allowed_scope:{room_tools_only:true}});await store.refresh();taskForm.value={title:'',description:'',acceptance_criteria:'',target_username:''};close();sidebar.value='tasks'})}
function startBinding(){bindingForm.value={host_kind:'codex',scope:'project',label:'',host_ref:'',executable:s.connection.mcp_executable};open('bind')}
async function bind(){await store.act(async()=>{const result=await transport<Connection>('bindAgent',{...bindingForm.value,room_id:s.roomId,session_key:s.connection.session_key});s.connection=result;selectedBinding.value=result.bindings.at(-1)||null;await store.refresh();modal.value='config'})}
function agentDetails(a:Agent){selectedAgent.value=a;selectedBinding.value=s.connection.bindings.find(b=>b.agent_id===a.id)||null;open('agent')}
async function toggleReply(){const a=selectedAgent.value;if(!a)return;await store.act(async()=>{await store.request('PATCH',`/v1/agents/${a.id}`,{auto_reply_enabled:!a.auto_reply_enabled});await store.refresh();selectedAgent.value=s.agents.find(x=>x.id===a.id)||null;s.notice='已更新发言许可；这不会自动唤醒宿主。'})}
async function probe(){if(!selectedBinding.value)return;await store.act(async()=>{const result=await transport<{message:string}>('probeBinding',{binding_id:selectedBinding.value!.id,session_key:s.connection.session_key});s.notice=result.message})}
async function revoke(){const a=selectedAgent.value;if(!a)return;await store.act(async()=>{if(selectedBinding.value)s.connection=await transport<Connection>('unbind',{binding_id:selectedBinding.value.id,session_key:s.connection.session_key});else await store.request('DELETE',`/v1/agents/${a.id}`);await store.refresh();close();s.notice='接入已撤销，旧令牌立即失效。宿主里的旧配置可移除，重新接入需创建新身份。'})}
async function taskDetails(t:Task){selectedTask.value=t;artifacts.value=[];artifact.value=null;run.value=null;permit.value='';authorizeAgent.value='';reviewReason.value='';open('task');const epoch=s.epoch;await store.act(async()=>{const rows=await store.request<Artifact[]>('GET',`/v1/tasks/${t.id}/artifact`);if(epoch===s.epoch&&selectedTask.value?.id===t.id)artifacts.value=rows})}
async function readArtifact(a:Artifact){const epoch=s.epoch;await store.act(async()=>{const result=await store.request<Artifact>('GET',`/v1/tasks/${a.task_id}/artifact/${a.id}`);const actualRun=await store.request<Record<string,unknown>>('GET',`/v1/runs/${a.run_id}`);if(epoch===s.epoch&&selectedTask.value?.id===a.task_id){artifact.value=result;run.value=actualRun}})}
async function authorize(){const task=selectedTask.value;if(!task||!authorizeAgent.value)return;await store.act(async()=>{const result=await store.request<{authorization_token:string;expires_at:string}>('POST',`/v1/tasks/${task.id}/authorize`,{agent_instance_id:authorizeAgent.value,expected_version:task.version});permit.value=result.authorization_token;permitExpiry.value=result.expires_at})}
async function review(decision:string){if(!selectedTask.value||!artifact.value)return;await store.act(async()=>{await store.request('POST',`/v1/tasks/${selectedTask.value!.id}/review`,{decision,artifact_id:artifact.value!.id,reason:reviewReason.value});await store.refresh();selectedTask.value=s.tasks.find(t=>t.id===selectedTask.value?.id)||null;s.notice=decision==='accepted'?'成果已验收':'成果已退回，等待负责人处理'})}
let poll:ReturnType<typeof setInterval>|undefined
function visibility(){if(!document.hidden&&!s.busy&&!s.loading)void store.refresh()}
onMounted(async()=>{await store.restore();poll=setInterval(visibility,5000);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{clearInterval(poll);document.removeEventListener('visibilitychange',visibility);permit.value='';form.value.password=''})
</script>

<template>
  <div class="workspace">
    <aside class="projects">
      <div class="brand"><span class="brand-mark"><PhChatsCircle weight="fill"/></span><div><b>EM Use</b><small>项目协作</small></div></div>
      <div class="rail-label">我的项目 <button :disabled="!s.connection.user||s.busy" aria-label="创建项目" @click="open('project')"><PhPlus/></button></div>
      <nav aria-label="项目列表"><button v-for="(p,index) in s.rooms" :key="p.id" class="project-link" :class="{selected:p.id===s.roomId}" :disabled="s.busy" @click="store.selectRoom(p.id)"><span class="project-index">{{String(index+1).padStart(2,'0')}}</span><span>{{p.name}}</span><span v-if="p.id===s.roomId" class="selection-dot"/></button></nav>
      <p v-if="s.connection.user&&!s.rooms.length&&!s.loading" class="rail-empty">还没有项目。<br/>从一个共同目标开始。</p>
      <div class="rail-bottom"><span class="rail-note">对话有归属，成果有来处。</span><button class="account" @click="form.server_url=s.connection.server_url||form.server_url;open('connection')"><span class="avatar human">{{s.connection.user?.display_name.slice(0,1)||'我'}}</span><span><b>{{s.connection.user?.display_name||'连接协作服务'}}</b><small>{{s.connection.user?'协作账户':'自建服务 · 独立账户'}}</small></span><PhGearSix/></button></div>
    </aside>

    <main v-if="!s.connection.user" class="welcome">
      <div class="welcome-art" aria-hidden="true"><span>DSH</span><i>＋</i><span>AiWork</span><i>＋</i><span>Codex</span></div>
      <span class="eyebrow">A ROOM FOR YOUR AGENTS</span><h1>一个项目，<br/>一起往前做。</h1><p>把不同工具里的 Agent 带进同一个房间。<br/>留下讨论、分工和每一次可复核的成果。</p>
      <button class="primary" :disabled="s.loading" @click="open('connection')"><PhPlug/>{{s.loading?'正在恢复连接…':'连接协作服务'}}</button>
      <p class="small">{{native?'登录凭据保存在系统钥匙串。':'浏览器预览：登录仅保留在内存，本机 Agent 接入请使用桌面应用。'}}</p>
      <div v-if="s.error" role="alert" class="alert">{{s.error}} <button @click="store.restore()">重试恢复</button></div>
    </main>
    <main v-else-if="!room" class="welcome"><span class="eyebrow">START A PROJECT</span><h1>给协作留个位置。</h1><p>一个项目对应一个固定房间。关闭窗口后，<br/>消息、任务和成果依然留在这里。</p><button class="primary" @click="open('project')"><PhPlus/>创建第一个项目</button><button class="text-button" @click="store.act(store.loadRooms)">刷新项目列表</button><div v-if="s.error" role="alert" class="alert">{{s.error}}</div></main>
    <div v-else class="project-space">
      <header class="project-header"><div><span class="eyebrow">PROJECT ROOM</span><h1>{{room.name}}</h1><p>{{s.members.length}} 位成员 · {{s.agents.length}} 个 Agent <span class="divider">/</span> 固定项目房间</p></div><div class="header-actions"><button class="subtle" @click="editContext"><PhFileText/>项目背景</button><button class="subtle" @click="open('members')"><PhUsers/>成员</button><button class="icon" :disabled="s.loading||s.busy" aria-label="刷新项目" @click="store.act(async()=>{await store.loadRooms();await store.refresh()})"><PhArrowsClockwise :class="{spinning:s.loading}"/></button></div></header>
      <div v-if="s.error" role="alert" class="alert">{{s.error}}<button :disabled="s.busy" @click="store.refresh()">重试读取</button></div>
      <div v-if="s.notice&&!modal" role="status" class="notice">{{s.notice}}</div>
      <div class="room-body">
        <section class="conversation" aria-label="项目对话">
          <div class="conversation-bar"><b><PhChatsCircle/>项目对话</b><span>{{s.refreshedAt?`同步于 ${time(s.refreshedAt)}`:'读取中'}}</span></div>
          <div class="trigger-note"><span class="status-dot"/>手动触发模式<span>发送后，到对应宿主让 Agent 读取房间。</span></div>
          <div ref="list" class="message-list" aria-live="polite" aria-relevant="additions">
            <div v-if="!s.messages.length" class="empty-conversation"><PhChatsCircle/><h2>让讨论从这里开始</h2><p>写下目标、问题或进展。<br/>Agent 的真实回复会带着身份回到房间。</p></div>
            <article v-for="m in s.messages" :key="m.id" class="message" :class="{mine:m.sender_user_id===s.connection.user?.id&&!m.sender_agent_instance_id}"><div class="avatar" :class="m.sender_agent_instance_id?'agent':'human'">{{sender(m).slice(0,1)}}</div><div class="message-content"><div class="message-byline"><b>{{sender(m)}}</b><span class="host-tag">{{host(m)}}</span><time :title="m.created_at">{{time(m.created_at)}}</time><button class="reply-button" :aria-label="`回复 ${sender(m)} 的消息`" @click="s.replyId=m.id"><PhArrowBendUpLeft/></button></div><div v-if="m.reply_to_id" class="reply-reference">回复 #{{s.messages.find(x=>x.id===m.reply_to_id)?.seq||m.reply_to_id.slice(0,8)}}</div><p>{{m.body}}</p><span class="message-seq">#{{m.seq}}</span></div></article>
            <button v-if="s.messages.length>=200" class="text-button" :disabled="s.loading" @click="store.refresh()">继续同步后续消息</button>
          </div>
          <form class="composer" @submit.prevent="store.send()"><div v-if="reply" class="reply-banner">回复 {{sender(reply)}} · #{{reply.seq}}<button type="button" aria-label="取消回复" @click="s.replyId=''"><PhX/></button></div><textarea v-model="draft" aria-label="项目消息" placeholder="写下目标、问题，或分享新的进展…" maxlength="20000" rows="3" @keydown.ctrl.enter.prevent="store.send()" @keydown.meta.enter.prevent="store.send()"/><div class="composer-footer"><span>⌘ / Ctrl + Enter 发送 · 不自动启动任务</span><button type="submit" class="primary" :disabled="s.busy||!draft.trim()"><PhArrowUp/>发送</button></div></form>
        </section>
        <aside class="room-sidebar"><div class="side-tabs"><button :class="{active:sidebar==='agents'}" @click="sidebar='agents'">Agent <span>{{s.agents.length}}</span></button><button :class="{active:sidebar==='tasks'}" @click="sidebar='tasks'">任务 <span>{{s.tasks.length}}</span></button></div>
          <template v-if="sidebar==='agents'"><div class="sidebar-heading"><span>这个项目的伙伴</span><button aria-label="接入 Agent" @click="startBinding"><PhPlus/></button></div><button v-for="a in s.agents" :key="a.id" class="agent-card" @click="agentDetails(a)"><div class="agent-top"><span class="avatar agent">{{hostNames[a.host_kind]?.slice(0,1)||'A'}}</span><div><b>{{a.label}}</b><small>{{hostNames[a.host_kind]||a.host_kind}} · {{a.owner_username}}</small></div></div><span class="agent-status"><i/>{{connectionLabel(a)}}</span><span class="manual-label">手动触发 · {{a.auto_reply_enabled?'允许房间回复':'尚未允许回复'}}</span></button><div v-if="!s.agents.length" class="side-empty"><PhPlug/><p>把你的 Agent<br/>带到这个项目里。</p></div><button class="outline full" @click="startBinding"><PhPlus/>接入 Agent</button><div class="sidebar-footnote">绑定成功只确认身份。<br/>在线状态与任务运行分别核实。</div></template>
          <template v-else><div class="sidebar-heading"><span>分工与交付</span><button aria-label="创建任务" @click="open('newTask')"><PhPlus/></button></div><button v-for="t in s.tasks" :key="t.id" class="task-card" @click="taskDetails(t)"><span class="task-status" :class="t.status">{{taskNames[t.status]||t.status}}</span><b>{{t.title}}</b><small>v{{t.version}} · {{t.assignee_user_id?s.members.find(m=>m.user_id===t.assignee_user_id)?.display_name||'成员':'尚未领取'}}</small></button><div v-if="!s.tasks.length" class="side-empty"><PhCheckCircle/><p>把讨论变成<br/>一件有完成条件的事。</p></div><button class="outline full" @click="open('newTask')"><PhPlus/>创建任务</button><div class="sidebar-footnote">执行完成 ≠ 已验收。<br/>成果由发布者或管理员确认。</div></template>
        </aside>
      </div>
    </div>
    <dialog ref="dialog" class="dialog" @cancel.prevent="close()" @close="close()">
      <header><span class="eyebrow">EM USE / {{room?.name||'COLLABORATION'}}</span><button class="icon" aria-label="关闭对话框" @click="close()"><PhX/></button></header>
      <div v-if="s.error" class="alert" role="alert">{{s.error}}</div><div v-if="s.notice" class="notice" role="status">{{s.notice}}</div>
      <template v-if="modal==='connection'"><h2>{{s.connection.user?'协作服务':'连接你的协作服务'}}</h2><template v-if="s.connection.user"><p>{{s.connection.user.display_name}} · {{s.connection.user.username}}</p><code>{{s.connection.server_url}}</code><p>协作账户与额度账户独立。退出不会删除项目或撤销 Agent。</p><button class="outline" :disabled="s.busy" @click="store.disconnect()">退出协作账户</button></template><form v-else @submit.prevent="login"><label>服务地址<input v-model="form.server_url" type="url" required placeholder="https://agents.example.com"/></label><label>接入方式<select v-model="form.mode"><option value="login">已有账户登录</option><option value="register">使用邀请注册</option><option value="bootstrap">首次部署：创建管理员</option></select></label><label>用户名<input v-model="form.username" autocomplete="username" required/></label><label v-if="form.mode!=='login'">显示名称<input v-model="form.display_name" required/></label><label v-if="form.mode==='register'">邀请码<input v-model="form.invite_token" required autocomplete="off"/></label><label>密码<input v-model="form.password" type="password" :autocomplete="form.mode==='login'?'current-password':'new-password'" required :minlength="form.mode==='login'?1:8"/></label><p class="small">{{native?'凭据保存在系统钥匙串，项目内容由你配置的服务存储。':'浏览器登录不持久化；刷新后需重新登录。'}}首次创建管理员仅对空服务有效。</p><button class="primary" :disabled="s.busy">{{s.busy?'连接中…':'连接'}}</button></form></template>
      <form v-if="modal==='project'" @submit.prevent="addProject"><h2>创建项目房间</h2><p>给一段持续的协作，一个固定入口。</p><label>项目名称<input v-model="projectName" autofocus required maxlength="100" placeholder="例如：桌宠协作一期"/></label><button class="primary" :disabled="s.busy||!projectName.trim()">创建项目</button></form>
      <form v-if="modal==='context'" @submit.prevent="saveContext"><h2>项目背景</h2><p>共同目标、范围与约定。Agent 可以读取这份背景；保存使用版本校验，避免覆盖他人的更新。</p><textarea v-model="contextDraft" aria-label="项目背景正文" rows="12" maxlength="30000" :readonly="!canEditContext"/><small>编辑基于 v{{contextVersion}}</small><footer><button type="button" class="outline" @click="store.act(async()=>{await store.refresh();editContext()})">重新载入</button><button v-if="canEditContext" class="primary" :disabled="s.busy||!contextDraft.trim()">保存背景</button></footer></form>
      <template v-if="modal==='members'"><h2>项目成员</h2><div v-for="m in s.members" :key="m.user_id" class="member-row"><span class="avatar human">{{m.display_name.slice(0,1)}}</span><b>{{m.display_name}}</b><small>{{m.username}} · {{m.role}}</small></div><section v-if="s.connection.user?.is_admin"><button class="outline" :disabled="s.busy" @click="invite">生成一次性注册邀请</button><template v-if="invitation"><p class="small">24 小时内有效。对方注册后，再用用户名添加到项目。关闭后不显示邀请码。</p><textarea :value="invitation" readonly rows="2" aria-label="注册邀请码"/><button class="outline" @click="copy(invitation)">{{copied?'已复制':'复制邀请码'}}</button></template></section><form v-if="['owner','admin'].includes(room?.role||'')" @submit.prevent="addMember"><label>添加已注册成员<input v-model="memberName" required placeholder="填写协作账户用户名"/></label><button class="primary" :disabled="s.busy">添加成员</button></form></template>
      <form v-if="modal==='newTask'" @submit.prevent="addTask"><h2>创建一件可交付的任务</h2><label>任务名称<input v-model="taskForm.title" required maxlength="160"/></label><label>任务说明<textarea v-model="taskForm.description" rows="3" required/></label><label>完成条件<textarea v-model="taskForm.acceptance_criteria" rows="3" required placeholder="怎样的成果才算完成？"/></label><label>负责人<select v-model="taskForm.target_username"><option value="">项目成员自由领取</option><option v-for="m in s.members" :key="m.user_id" :value="m.username">{{m.display_name}} · {{m.username}}</option></select></label><p class="small">本版任务限定房间工具，只读复核与提交成果。Agent 领取后仍需你签发执行许可，不会自动运行代码。</p><button class="primary" :disabled="s.busy">创建任务</button></form>
      <form v-if="modal==='bind'" @submit.prevent="bind"><h2>把 Agent 带进项目</h2><p>一个独立身份，对应一个明确的宿主会话或配置范围。</p><div v-if="!native" class="notice">浏览器不操作本机钥匙串。请从桌宠设置或托盘打开「项目协作」完成接入。</div><label>Agent 宿主<select v-model="bindingForm.host_kind"><option v-for="(name,id) in hostNames" :key="id" :value="id">{{name}}</option></select></label><label>房间中的名称<input v-model="bindingForm.label" required maxlength="100" placeholder="例如：方案复核 · Codex"/></label><label>绑定范围<select v-model="bindingForm.scope" :disabled="bindingForm.host_kind==='dsh'"><option value="session">独立会话</option><option value="project">项目配置</option><option value="profile">独立 profile</option></select></label><label>宿主会话 ID / 项目路径 / profile<input v-model="bindingForm.host_ref" required placeholder="用于固定对应关系，不会自动接管宿主窗口"/></label><p v-if="s.connection.mcp_executable" class="notice">已使用应用内置 MCP，无需另行安装。<code>{{s.connection.mcp_executable}}</code></p><label v-else>MCP 程序完整路径<input v-model="bindingForm.executable" required placeholder="未找到内置 MCP，请重新安装完整应用或指定程序"/></label><p class="small">{{configInstructions(bindingForm.host_kind)}} 这里登记对应关系，不代表已核验宿主实际会话。</p><button class="primary" :disabled="s.busy||!native">创建独立身份并生成配置</button></form>
      <template v-if="modal==='config'&&selectedBinding"><h2>配置已生成，下一步连接宿主</h2><p>{{selectedBinding.label}} · {{hostNames[selectedBinding.host_kind]}}</p><div class="notice">{{configInstructions(selectedBinding.host_kind)}}</div><pre class="config"><code>{{bindConfig}}</code></pre><button class="outline" @click="copy(bindConfig)"><PhCopy/>{{copied?'已复制':'复制配置'}}</button><ol class="steps"><li>将配置合并到上面指定的宿主范围，保留原配置。</li><li>在宿主中让 Agent 调用 room_read，确认房间 ID：<code>{{selectedBinding.room_id}}</code>。</li><li>在 Agent 详情中开启房间回复，再发送测试消息。尚未验证的宿主请保留手动触发。</li></ol><button class="primary" @click="close()">完成配置指引</button></template>
      <template v-if="modal==='agent'&&selectedAgent"><h2>{{selectedAgent.label}}</h2><p>{{hostNames[selectedAgent.host_kind]}} · {{connectionLabel(selectedAgent)}}</p><dl><dt>Agent 身份</dt><dd>{{selectedAgent.id}}</dd><dt>所属成员</dt><dd>{{selectedAgent.owner_username}}</dd><dt>本机会话记录</dt><dd>{{selectedBinding?.host_ref||'该身份未在当前设备登记'}}</dd><dt>范围</dt><dd>{{selectedBinding?.scope||'未登记'}} · 不自动控制宿主</dd></dl><template v-if="selectedAgent.owner_user_id===s.connection.user?.id"><div class="button-row"><button v-if="selectedBinding" class="outline" @click="modal='config'">查看配置</button><button v-if="selectedBinding" class="outline" :disabled="s.busy" @click="probe">验证房间凭据</button></div><button class="outline full" :disabled="s.busy" @click="toggleReply">{{selectedAgent.auto_reply_enabled?'关闭房间回复':'允许 Agent 在房间回复'}}</button><p class="small">回复只响应明确的消息，受频率和连续回复限制。这个开关不会启动 Agent。</p><button class="text-button danger" @click="modal='revoke'">撤销接入…</button></template></template>
      <template v-if="modal==='revoke'&&selectedAgent"><h2>撤销 {{selectedAgent.label}} 的接入？</h2><p>旧令牌立即失效。历史消息与成果保留；本操作不承诺停止宿主中已经运行的工作。</p><button class="danger-button" :disabled="s.busy" @click="revoke">确认撤销接入</button></template>
      <template v-if="modal==='task'&&selectedTask"><span class="task-status" :class="selectedTask.status">{{taskNames[selectedTask.status]||selectedTask.status}}</span><h2>{{selectedTask.title}}</h2><p class="pre-wrap">{{selectedTask.description}}</p><h3>完成条件</h3><p class="pre-wrap">{{selectedTask.acceptance_criteria}}</p><p class="small">任务 {{selectedTask.id}} · v{{selectedTask.version}}</p><div v-if="selectedTask.blocked_reason" class="alert">{{selectedTask.blocked_reason}}</div><div v-if="selectedTask.status==='pending'" class="notice">等待负责人在宿主中调用 task_list、task_claim 领取。任务消息不会自动唤醒宿主。</div><section v-if="['claimed','failed','blocked'].includes(selectedTask.status)&&selectedTask.assignee_user_id===s.connection.user?.id" class="permit-box"><h3>签发一次执行许可</h3><p class="small">选择本人的 Agent。许可绑定任务当前版本和 Agent，短期有效且只能使用一次。</p><label>执行 Agent<select v-model="authorizeAgent"><option value="">请选择</option><option v-for="a in mine" :key="a.id" :value="a.id">{{a.label}}</option></select></label><button class="outline" :disabled="s.busy||!authorizeAgent||!!permit" @click="authorize">签发许可</button><template v-if="permit"><p>有效至 {{time(permitExpiry)}}。关闭此窗口后不保留明文。</p><textarea :value="permitPrompt" readonly rows="5" aria-label="单次任务执行指令"/><button class="outline" @click="copy(permitPrompt)"><PhCopy/>{{copied?'已复制':'复制给指定 Agent'}}</button></template></section><h3>提交的成果</h3><p v-if="!artifacts.length" class="small">尚无成果。运行成功后也需要人工核验。</p><button v-for="a in artifacts" :key="a.id" class="artifact-row" :disabled="s.busy" @click="readArtifact(a)"><PhFileText/><span>{{a.kind}} · {{a.size_bytes}} B<small>{{a.id}}</small></span><PhArrowSquareOut/></button><section v-if="artifact" class="artifact-detail"><div class="notice">Run：{{run?.status}} · 成果哈希：{{artifact.content_hash}}</div><p>{{artifact.verification_summary}}</p><pre>{{artifact.content}}</pre><template v-if="selectedTask.status==='pending_review'&&canReview"><label>验收说明<textarea v-model="reviewReason" rows="2" placeholder="验收依据，或需要修改的地方"/></label><footer><button class="outline" :disabled="s.busy||!reviewReason.trim()" @click="review('rejected')">退回修改</button><button class="primary" :disabled="s.busy" @click="review('accepted')"><PhCheckCircle/>验收此成果</button></footer></template></section></template>
    </dialog>
  </div>
</template>
